-- Silver Thief Bug: 100 demo products for presenting the shop (64 live beetles, 12 food, 12 logs &
-- substrate, 12 gear), each with Thai and English names and descriptions, Beetle Attributes for
-- beetles, stock, and 1–3 photos.
--
-- Run in the Supabase SQL Editor after migration 006 (and clear_products.sql if you want only these).
-- Safe to run again: a product whose English name already exists is skipped.
-- Each new product starts its Stock History with one "created" entry (the stock trigger), noted
-- "Demo data".
--
-- Photos are freely licensed images on Wikimedia Commons, linked (not copied). CC BY / CC BY-SA
-- require credit: see demo_photo_credits.md beside this file. Replace them with the shop's own photos
-- before selling for real.
--
-- Generated from a catalogue script; edit the data there rather than by hand where you can.

BEGIN;

-- The Families these beetles use (kept if they already exist)
INSERT INTO public.beetle_families (name, sort_order) VALUES
  ('Rhinoceros', 1), ('Stag', 2), ('Flower', 3)
ON CONFLICT (name) DO NOTHING;

-- Their first Stock History entries say where they came from
SELECT public.stock_context('created', NULL, NULL, 'Demo data');

INSERT INTO public.products
  (name, name_th, description, description_th, price, on_hand, available, category, attributes, images, is_best_seller, is_active, views)
SELECT v.name, v.name_th, v.description, v.description_th, v.price, v.stock, v.stock, v.category, v.attributes, v.images, v.best, TRUE, v.views
FROM (VALUES
  ('Hercules beetle (Dynastes hercules hercules), male', 'ด้วงเฮอร์คิวลิส (Dynastes hercules hercules) ตัวผู้', 'The longest beetle in the world: males carry a horn as long as their body and change wing colour from olive to black with humidity. Size about 152 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงที่ยาวที่สุดในโลก ตัวผู้มีเขายาวพอๆ กับลำตัว และปีกเปลี่ยนสีจากเขียวมะกอกเป็นดำตามความชื้น ขนาดประมาณ 152 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 8500, 2, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes hercules hercules", "locality": "Guadeloupe", "sex": "male", "stage": "adult", "size_mm": 152}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Dynastes_hercules_ecuatorianus_MHNT.jpg/1280px-Dynastes_hercules_ecuatorianus_MHNT.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Dynastes_hercules_%28female%29.jpg/1280px-Dynastes_hercules_%28female%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/0/09/Hercules_beetle_%28Dynastes_hercules%29%2C_Entomica.jpg']::TEXT[], TRUE, 2800),
  ('Hercules beetle (Dynastes hercules hercules), pair (1 male + 1 female)', 'ด้วงเฮอร์คิวลิส (Dynastes hercules hercules) คู่ (ผู้ 1 เมีย 1)', 'The longest beetle in the world: males carry a horn as long as their body and change wing colour from olive to black with humidity. Size about 140 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงที่ยาวที่สุดในโลก ตัวผู้มีเขายาวพอๆ กับลำตัว และปีกเปลี่ยนสีจากเขียวมะกอกเป็นดำตามความชื้น ขนาดประมาณ 140 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 12500, 1, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes hercules hercules", "locality": "Guadeloupe", "sex": "pair", "stage": "adult", "size_mm": 140}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Dynastes_hercules_%28female%29.jpg/1280px-Dynastes_hercules_%28female%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/0/09/Hercules_beetle_%28Dynastes_hercules%29%2C_Entomica.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Dynastes_hercules_ecuatorianus_MHNT.jpg/1280px-Dynastes_hercules_ecuatorianus_MHNT.jpg']::TEXT[], FALSE, 1271),
  ('Hercules beetle (Dynastes hercules hercules), L3 larva', 'ด้วงเฮอร์คิวลิส (Dynastes hercules hercules) หนอนระยะ L3', 'The longest beetle in the world: males carry a horn as long as their body and change wing colour from olive to black with humidity. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'ด้วงที่ยาวที่สุดในโลก ตัวผู้มีเขายาวพอๆ กับลำตัว และปีกเปลี่ยนสีจากเขียวมะกอกเป็นดำตามความชื้น เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 1800, 6, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes hercules hercules", "locality": "Guadeloupe", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg/1280px-%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Allomyrina_dichotoma_L3_Larva.JPG/1280px-Allomyrina_dichotoma_L3_Larva.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Dynastes_hercules_ecuatorianus_MHNT.jpg/1280px-Dynastes_hercules_ecuatorianus_MHNT.jpg']::TEXT[], FALSE, 902),
  ('Lichy Hercules beetle (Dynastes hercules lichyi), male', 'ด้วงเฮอร์คิวลิส ลิชี่ (Dynastes hercules lichyi) ตัวผู้', 'An Andean Hercules with pale, almost cream wing cases and a long, thin upper horn. Size about 138 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'เฮอร์คิวลิสสายเทือกเขาแอนดีส ปีกสีครีมอ่อน เขาบนยาวเรียว ขนาดประมาณ 138 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 6900, 2, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes hercules lichyi", "locality": "Peru", "sex": "male", "stage": "adult", "size_mm": 138}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Dynastes_hercules_ecuatorianus_MHNT.jpg/1280px-Dynastes_hercules_ecuatorianus_MHNT.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Dynastes_hercules_lichyi_%28Lachaume%2C_1985%29_female_%288538216877%29.png/1280px-Dynastes_hercules_lichyi_%28Lachaume%2C_1985%29_female_%288538216877%29.png', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Dynastes_hercules_lichyi_%28Lachaume%2C_1985%29_male_%288538222465%29.png/1280px-Dynastes_hercules_lichyi_%28Lachaume%2C_1985%29_male_%288538222465%29.png']::TEXT[], FALSE, 733),
  ('Neptune beetle (Dynastes neptunus), male', 'ด้วงเนปจูน (Dynastes neptunus) ตัวผู้', 'Shiny black with three forward horns; a rarer relative of the Hercules from Andean cloud forest. Size about 122 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีดำเงา มีเขาชี้ไปข้างหน้าสามเขา ญาติที่หายากกว่าของเฮอร์คิวลิส จากป่าเมฆเทือกเขาแอนดีส ขนาดประมาณ 122 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 7900, 1, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes neptunus", "locality": "Colombia", "sex": "male", "stage": "adult", "size_mm": 122}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Dynastes_neptunus_001.jpg/1280px-Dynastes_neptunus_001.jpg', 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Dynastes_neptunus_m2.jpg']::TEXT[], FALSE, 664),
  ('Eastern Hercules beetle (Dynastes tityus), pair (1 male + 1 female)', 'ด้วงเฮอร์คิวลิสตะวันออก (Dynastes tityus) คู่ (ผู้ 1 เมีย 1)', 'A North American Dynastes with spotted grey-green wing cases; calm and easy to keep. Size about 55 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงสกุล Dynastes จากอเมริกาเหนือ ปีกสีเทาเขียวมีจุด นิสัยนิ่ง เลี้ยงง่าย ขนาดประมาณ 55 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1600, 4, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes tityus", "locality": "USA", "sex": "pair", "stage": "adult", "size_mm": 55}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Dynastes_tityus_SC.jpg/1280px-Dynastes_tityus_SC.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Dynastes_tityus_UMFS_2.jpg/1280px-Dynastes_tityus_UMFS_2.jpg']::TEXT[], FALSE, 2295),
  ('Western Hercules beetle (Dynastes granti), male', 'ด้วงเฮอร์คิวลิสตะวันตก (Dynastes granti) ตัวผู้', 'Pale grey with dark spots and a long thoracic horn; a desert-edge species that handles dry air well. Size about 72 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเทาอ่อนลายจุดดำ เขาอกยาว อยู่แถบขอบทะเลทราย ทนอากาศแห้งได้ดี ขนาดประมาณ 72 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2900, 3, 'beetle', '{"family": "Rhinoceros", "species": "Dynastes granti", "locality": "Arizona, USA", "sex": "male", "stage": "adult", "size_mm": 72}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Dynastes_granti_pair.JPG/1280px-Dynastes_granti_pair.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Dynastes_granti_m2.jpg/1280px-Dynastes_granti_m2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Dynastes_granti_f2.jpg/1280px-Dynastes_granti_f2.jpg']::TEXT[], FALSE, 1926),
  ('Elephant beetle (Megasoma elephas), male', 'ด้วงช้าง (Megasoma elephas) ตัวผู้', 'One of the heaviest beetles alive, covered in fine golden hair over a black shell. Size about 112 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'หนึ่งในด้วงที่หนักที่สุดในโลก ตัวดำปกคลุมด้วยขนละเอียดสีทอง ขนาดประมาณ 112 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 5500, 2, 'beetle', '{"family": "Rhinoceros", "species": "Megasoma elephas", "locality": "Mexico", "sex": "male", "stage": "adult", "size_mm": 112}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Elephant_beetle_%28Megasoma_elephas%29.jpg/1280px-Elephant_beetle_%28Megasoma_elephas%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Elephant_beetle_%28Megasoma_elephas%29_face.jpg/1280px-Elephant_beetle_%28Megasoma_elephas%29_face.jpg']::TEXT[], TRUE, 1917),
  ('Elephant beetle (Megasoma elephas), L3 larva', 'ด้วงช้าง (Megasoma elephas) หนอนระยะ L3', 'One of the heaviest beetles alive, covered in fine golden hair over a black shell. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'หนึ่งในด้วงที่หนักที่สุดในโลก ตัวดำปกคลุมด้วยขนละเอียดสีทอง เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 900, 8, 'beetle', '{"family": "Rhinoceros", "species": "Megasoma elephas", "locality": "Mexico", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg/1280px-%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Allomyrina_dichotoma_L3_Larva.JPG/1280px-Allomyrina_dichotoma_L3_Larva.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Elephant_beetle_%28Megasoma_elephas%29.jpg/1280px-Elephant_beetle_%28Megasoma_elephas%29.jpg']::TEXT[], FALSE, 188),
  ('Actaeon beetle (Megasoma actaeon), male', 'ด้วงแอคเทออน (Megasoma actaeon) ตัวผู้', 'A massive, glossy black giant from South America; among the heaviest insects by mass. Size about 118 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงยักษ์สีดำเงาจากอเมริกาใต้ หนึ่งในแมลงที่หนักที่สุด ขนาดประมาณ 118 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 9800, 1, 'beetle', '{"family": "Rhinoceros", "species": "Megasoma actaeon", "locality": "Guyana", "sex": "male", "stage": "adult", "size_mm": 118}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Megasoma_actaeon_MHNT_Femelle.jpg/1280px-Megasoma_actaeon_MHNT_Femelle.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Megasoma_actaeon_f.jpg/1280px-Megasoma_actaeon_f.jpg']::TEXT[], FALSE, 219),
  ('Atlas beetle (Chalcosoma atlas), male', 'ด้วงกว่างสามเขา (Chalcosoma atlas) ตัวผู้', 'The classic three-horned rhinoceros beetle of Southeast Asia, with a bronze-green sheen. Size about 98 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงกว่างสามเขาแห่งเอเชียตะวันออกเฉียงใต้ ผิวมันวาวสีเขียวอมทองแดง ขนาดประมาณ 98 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1200, 9, 'beetle', '{"family": "Rhinoceros", "species": "Chalcosoma atlas", "locality": "Chiang Mai, Thailand", "sex": "male", "stage": "adult", "size_mm": 98}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Chalcosoma_atlas_m.jpg/1280px-Chalcosoma_atlas_m.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Chalcosoma_atlas_f2.jpg/1280px-Chalcosoma_atlas_f2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Atlas_Beetle_-_Zachi_Evenor.jpg/1280px-Atlas_Beetle_-_Zachi_Evenor.jpg']::TEXT[], TRUE, 1010),
  ('Atlas beetle (Chalcosoma atlas), pair (1 male + 1 female)', 'ด้วงกว่างสามเขา (Chalcosoma atlas) คู่ (ผู้ 1 เมีย 1)', 'The classic three-horned rhinoceros beetle of Southeast Asia, with a bronze-green sheen. Size about 92 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงกว่างสามเขาแห่งเอเชียตะวันออกเฉียงใต้ ผิวมันวาวสีเขียวอมทองแดง ขนาดประมาณ 92 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1800, 6, 'beetle', '{"family": "Rhinoceros", "species": "Chalcosoma atlas", "locality": "Chiang Mai, Thailand", "sex": "pair", "stage": "adult", "size_mm": 92}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Chalcosoma_atlas_f2.jpg/1280px-Chalcosoma_atlas_f2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Atlas_Beetle_-_Zachi_Evenor.jpg/1280px-Atlas_Beetle_-_Zachi_Evenor.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Chalcosoma_atlas_m.jpg/1280px-Chalcosoma_atlas_m.jpg']::TEXT[], FALSE, 2081),
  ('Atlas beetle (Chalcosoma atlas), 3 L3 larvae', 'ด้วงกว่างสามเขา (Chalcosoma atlas) หนอนระยะ L3 3 ตัว', 'The classic three-horned rhinoceros beetle of Southeast Asia, with a bronze-green sheen. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'ด้วงกว่างสามเขาแห่งเอเชียตะวันออกเฉียงใต้ ผิวมันวาวสีเขียวอมทองแดง เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 180, 20, 'beetle', '{"family": "Rhinoceros", "species": "Chalcosoma atlas", "locality": "Chiang Mai, Thailand", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg/1280px-%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Allomyrina_dichotoma_L3_Larva.JPG/1280px-Allomyrina_dichotoma_L3_Larva.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Chalcosoma_atlas_m.jpg/1280px-Chalcosoma_atlas_m.jpg']::TEXT[], FALSE, 472),
  ('Caucasus beetle (Chalcosoma caucasus), male', 'ด้วงคอเคซัส (Chalcosoma caucasus) ตัวผู้', 'The largest Chalcosoma (now also listed as C. chiron), with long curved horns and a metallic green-black shine. Size about 118 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงสกุล Chalcosoma ที่ใหญ่ที่สุด (ปัจจุบันจัดเป็น C. chiron) เขาโค้งยาว ผิวดำอมเขียวเหลือบโลหะ ขนาดประมาณ 118 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2500, 4, 'beetle', '{"family": "Rhinoceros", "species": "Chalcosoma caucasus", "locality": "Sumatra, Indonesia", "sex": "male", "stage": "adult", "size_mm": 118}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Chalcosoma_caucasus_f2.jpg/1280px-Chalcosoma_caucasus_f2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Chalcosoma_caucasus_f.jpg/1280px-Chalcosoma_caucasus_f.jpg']::TEXT[], FALSE, 43),
  ('Caucasus beetle (Chalcosoma caucasus), pair (1 male + 1 female)', 'ด้วงคอเคซัส (Chalcosoma caucasus) คู่ (ผู้ 1 เมีย 1)', 'The largest Chalcosoma (now also listed as C. chiron), with long curved horns and a metallic green-black shine. Size about 112 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงสกุล Chalcosoma ที่ใหญ่ที่สุด (ปัจจุบันจัดเป็น C. chiron) เขาโค้งยาว ผิวดำอมเขียวเหลือบโลหะ ขนาดประมาณ 112 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 3600, 2, 'beetle', '{"family": "Rhinoceros", "species": "Chalcosoma caucasus", "locality": "Sumatra, Indonesia", "sex": "pair", "stage": "adult", "size_mm": 112}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Chalcosoma_caucasus_f.jpg/1280px-Chalcosoma_caucasus_f.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Chalcosoma_caucasus_f2.jpg/1280px-Chalcosoma_caucasus_f2.jpg']::TEXT[], FALSE, 674),
  ('Fighting beetle (Xylotrupes gideon), male', 'ด้วงกว่างชน (Xylotrupes gideon) ตัวผู้', 'The Thai fighting beetle (กว่างชน): forked horns, a short adult life and a big temperament. A good first beetle. Size about 62 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กว่างชนของไทย เขาแฉก อายุตัวเต็มวัยไม่ยาวแต่ใจสู้ เหมาะเป็นด้วงตัวแรก ขนาดประมาณ 62 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 250, 25, 'beetle', '{"family": "Rhinoceros", "species": "Xylotrupes gideon", "locality": "Lampang, Thailand", "sex": "male", "stage": "adult", "size_mm": 62}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Xylotrupes_gideon_m.jpg/1280px-Xylotrupes_gideon_m.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Xylotrupes_gideon_f.jpg/1280px-Xylotrupes_gideon_f.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Xylotrupes_gideon.JPG/1280px-Xylotrupes_gideon.JPG']::TEXT[], TRUE, 2215),
  ('Fighting beetle (Xylotrupes gideon), pair (1 male + 1 female)', 'ด้วงกว่างชน (Xylotrupes gideon) คู่ (ผู้ 1 เมีย 1)', 'The Thai fighting beetle (กว่างชน): forked horns, a short adult life and a big temperament. A good first beetle. Size about 58 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กว่างชนของไทย เขาแฉก อายุตัวเต็มวัยไม่ยาวแต่ใจสู้ เหมาะเป็นด้วงตัวแรก ขนาดประมาณ 58 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 390, 15, 'beetle', '{"family": "Rhinoceros", "species": "Xylotrupes gideon", "locality": "Lampang, Thailand", "sex": "pair", "stage": "adult", "size_mm": 58}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Xylotrupes_gideon_f.jpg/1280px-Xylotrupes_gideon_f.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Xylotrupes_gideon.JPG/1280px-Xylotrupes_gideon.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Xylotrupes_gideon_m.jpg/1280px-Xylotrupes_gideon_m.jpg']::TEXT[], FALSE, 66),
  ('Fighting beetle (Xylotrupes gideon), 3 L3 larvae', 'ด้วงกว่างชน (Xylotrupes gideon) หนอนระยะ L3 3 ตัว', 'The Thai fighting beetle (กว่างชน): forked horns, a short adult life and a big temperament. A good first beetle. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'กว่างชนของไทย เขาแฉก อายุตัวเต็มวัยไม่ยาวแต่ใจสู้ เหมาะเป็นด้วงตัวแรก เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 150, 30, 'beetle', '{"family": "Rhinoceros", "species": "Xylotrupes gideon", "locality": "Lampang, Thailand", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg/1280px-%E3%82%AB%E3%83%96%E3%83%88%E3%83%A0%E3%82%B7_larva_as_a_pet_in_Tokyo.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Allomyrina_dichotoma_L3_Larva.JPG/1280px-Allomyrina_dichotoma_L3_Larva.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Xylotrupes_gideon_m.jpg/1280px-Xylotrupes_gideon_m.jpg']::TEXT[], FALSE, 917),
  ('Five-horned rhinoceros beetle (Eupatorus gracilicornis), male', 'ด้วงกว่างห้าเขา (Eupatorus gracilicornis) ตัวผู้', 'Five slender horns and cream-brown wing cases; a striking species from northern Thai forests. Size about 68 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'มีเขาเรียวห้าเขา ปีกสีน้ำตาลครีม ด้วงสวยจากป่าภาคเหนือของไทย ขนาดประมาณ 68 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1500, 5, 'beetle', '{"family": "Rhinoceros", "species": "Eupatorus gracilicornis", "locality": "Chiang Rai, Thailand", "sex": "male", "stage": "adult", "size_mm": 68}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Eupatorus_gracilicornis_Vol.jpg/1280px-Eupatorus_gracilicornis_Vol.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Eupatorus_gracilicornis_global.jpg/1280px-Eupatorus_gracilicornis_global.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Eupatorus_gracilicornis.jpg/1280px-Eupatorus_gracilicornis.jpg']::TEXT[], FALSE, 898),
  ('Five-horned rhinoceros beetle (Eupatorus gracilicornis), pair (1 male + 1 female)', 'ด้วงกว่างห้าเขา (Eupatorus gracilicornis) คู่ (ผู้ 1 เมีย 1)', 'Five slender horns and cream-brown wing cases; a striking species from northern Thai forests. Size about 64 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'มีเขาเรียวห้าเขา ปีกสีน้ำตาลครีม ด้วงสวยจากป่าภาคเหนือของไทย ขนาดประมาณ 64 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2200, 3, 'beetle', '{"family": "Rhinoceros", "species": "Eupatorus gracilicornis", "locality": "Chiang Rai, Thailand", "sex": "pair", "stage": "adult", "size_mm": 64}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Eupatorus_gracilicornis_global.jpg/1280px-Eupatorus_gracilicornis_global.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Eupatorus_gracilicornis.jpg/1280px-Eupatorus_gracilicornis.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Eupatorus_gracilicornis_Vol.jpg/1280px-Eupatorus_gracilicornis_Vol.jpg']::TEXT[], FALSE, 1129),
  ('Japanese rhinoceros beetle (Trypoxylus dichotomus), male', 'ด้วงกว่างญี่ปุ่น (Trypoxylus dichotomus) ตัวผู้', 'Kabutomushi: a hardy, fast-growing species with a forked head horn, loved by beginners. Size about 78 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'คาบูโตะมูชิ ด้วงแข็งแรง โตไว เขาหัวแตกแฉก เป็นที่นิยมของมือใหม่ ขนาดประมาณ 78 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 450, 12, 'beetle', '{"family": "Rhinoceros", "species": "Trypoxylus dichotomus", "locality": "Japan", "sex": "male", "stage": "adult", "size_mm": 78}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/3/39/Trypoxylus_dichotomus_135465060.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Trypoxylus_dichotomus_298634125.jpg/1280px-Trypoxylus_dichotomus_298634125.jpg']::TEXT[], FALSE, 1010),
  ('Japanese rhinoceros beetle (Trypoxylus dichotomus), pair (1 male + 1 female)', 'ด้วงกว่างญี่ปุ่น (Trypoxylus dichotomus) คู่ (ผู้ 1 เมีย 1)', 'Kabutomushi: a hardy, fast-growing species with a forked head horn, loved by beginners. Size about 74 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'คาบูโตะมูชิ ด้วงแข็งแรง โตไว เขาหัวแตกแฉก เป็นที่นิยมของมือใหม่ ขนาดประมาณ 74 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 690, 8, 'beetle', '{"family": "Rhinoceros", "species": "Trypoxylus dichotomus", "locality": "Japan", "sex": "pair", "stage": "adult", "size_mm": 74}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Trypoxylus_dichotomus_298634125.jpg/1280px-Trypoxylus_dichotomus_298634125.jpg', 'https://upload.wikimedia.org/wikipedia/commons/3/39/Trypoxylus_dichotomus_135465060.jpg']::TEXT[], FALSE, 421),
  ('Porter''s rhinoceros beetle (Golofa porteri), male', 'ด้วงโกโลฟา พอร์เทอรี (Golofa porteri) ตัวผู้', 'Long-legged and slender, with a hooked head horn longer than its body. Size about 82 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ขายาวลำตัวเพรียว เขาหัวงองุ้มยาวกว่าลำตัว ขนาดประมาณ 82 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2800, 2, 'beetle', '{"family": "Rhinoceros", "species": "Golofa porteri", "locality": "Venezuela", "sex": "male", "stage": "adult", "size_mm": 82}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Golofa_porteri_m.jpg/1280px-Golofa_porteri_m.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Golofa_porteri_283699421.jpg/1280px-Golofa_porteri_283699421.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Golofaporteri.JPG/1280px-Golofaporteri.JPG']::TEXT[], FALSE, 922),
  ('Coconut rhinoceros beetle (Oryctes rhinoceros), pair (1 male + 1 female)', 'ด้วงแรด (Oryctes rhinoceros) คู่ (ผู้ 1 เมีย 1)', 'The familiar Thai coconut beetle; tough, inexpensive and good for learning larval care. Size about 45 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงแรดมะพร้าวที่คุ้นเคยในไทย แข็งแรง ราคาไม่สูง เหมาะฝึกเลี้ยงหนอน ขนาดประมาณ 45 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 120, 20, 'beetle', '{"family": "Rhinoceros", "species": "Oryctes rhinoceros", "locality": "Nakhon Si Thammarat, Thailand", "sex": "pair", "stage": "adult", "size_mm": 45}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Oryctes_rhinoceros_male.jpg/1280px-Oryctes_rhinoceros_male.jpg']::TEXT[], FALSE, 1493),
  ('Centaur beetle (Augosoma centaurus), male', 'ด้วงเซนทอร์ (Augosoma centaurus) ตัวผู้', 'An African giant with two thick horns and a glossy chestnut-black shell. Size about 80 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงยักษ์แอฟริกา เขาหนาสองเขา ผิวดำอมน้ำตาลเงา ขนาดประมาณ 80 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2400, 2, 'beetle', '{"family": "Rhinoceros", "species": "Augosoma centaurus", "locality": "Cameroon", "sex": "male", "stage": "adult", "size_mm": 80}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Augosoma_centaurus_f.jpg/1280px-Augosoma_centaurus_f.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Augosoma_centaurus_m.jpg/1280px-Augosoma_centaurus_m.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Augosoma_centaurus_f2.jpg/1280px-Augosoma_centaurus_f2.jpg']::TEXT[], FALSE, 784),
  ('Giant stag beetle (Dorcus titanus), male', 'ด้วงคีมยักษ์ (Dorcus titanus) ตัวผู้', 'Broad, flat and powerful jaws; a long-lived stag that suits a calm keeper. Size about 92 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กรามใหญ่แบน ทรงพลัง อายุยืน เหมาะกับผู้เลี้ยงใจเย็น ขนาดประมาณ 92 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1500, 6, 'beetle', '{"family": "Stag", "species": "Dorcus titanus", "locality": "Phetchabun, Thailand", "sex": "male", "stage": "adult", "size_mm": 92}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/Dorcus_titanus_sjh.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/MP_-_Dorcus_titanus_2.jpg/1280px-MP_-_Dorcus_titanus_2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Dorcus_titanus_sika_%2830478223977%29.jpg/1280px-Dorcus_titanus_sika_%2830478223977%29.jpg']::TEXT[], TRUE, 2675),
  ('Giant stag beetle (Dorcus titanus), pair (1 male + 1 female)', 'ด้วงคีมยักษ์ (Dorcus titanus) คู่ (ผู้ 1 เมีย 1)', 'Broad, flat and powerful jaws; a long-lived stag that suits a calm keeper. Size about 88 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กรามใหญ่แบน ทรงพลัง อายุยืน เหมาะกับผู้เลี้ยงใจเย็น ขนาดประมาณ 88 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2100, 4, 'beetle', '{"family": "Stag", "species": "Dorcus titanus", "locality": "Phetchabun, Thailand", "sex": "pair", "stage": "adult", "size_mm": 88}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/MP_-_Dorcus_titanus_2.jpg/1280px-MP_-_Dorcus_titanus_2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Dorcus_titanus_sika_%2830478223977%29.jpg/1280px-Dorcus_titanus_sika_%2830478223977%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/c/c1/Dorcus_titanus_sjh.jpg']::TEXT[], FALSE, 1346),
  ('Hope''s stag beetle (Dorcus hopei), male', 'ด้วงคีมโฮเปอิ (Dorcus hopei) ตัวผู้', 'Ookuwagata: thick inward-curving jaws and a lifespan of several years as an adult. Size about 74 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'โอคุวากาตะ กรามหนาโค้งเข้าใน ตัวเต็มวัยอยู่ได้หลายปี ขนาดประมาณ 74 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1900, 3, 'beetle', '{"family": "Stag", "species": "Dorcus hopei", "locality": "China", "sex": "male", "stage": "adult", "size_mm": 74}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/6/6b/Dorcus_hopei.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Dorcushopeibinodulosus.JPG/1280px-Dorcushopeibinodulosus.JPG']::TEXT[], FALSE, 77),
  ('Hope''s stag beetle (Dorcus hopei), L3 larva', 'ด้วงคีมโฮเปอิ (Dorcus hopei) หนอนระยะ L3', 'Ookuwagata: thick inward-curving jaws and a lifespan of several years as an adult. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'โอคุวากาตะ กรามหนาโค้งเข้าใน ตัวเต็มวัยอยู่ได้หลายปี เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 350, 12, 'beetle', '{"family": "Stag", "species": "Dorcus hopei", "locality": "China", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Larva_of_hirata-kun.jpg/1280px-Larva_of_hirata-kun.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a3/Noko_larva.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/6b/Dorcus_hopei.jpg']::TEXT[], FALSE, 1358),
  ('Antaeus stag beetle (Dorcus antaeus), male', 'ด้วงคีมแอนเทียส (Dorcus antaeus) ตัวผู้', 'A glossy black stag with wide, toothed jaws from the cool mountains of northern Thailand. Size about 78 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมดำเงา กรามกว้างมีฟัน จากภูเขาเย็นของภาคเหนือ ขนาดประมาณ 78 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2600, 3, 'beetle', '{"family": "Stag", "species": "Dorcus antaeus", "locality": "Doi Inthanon, Thailand", "sex": "male", "stage": "adult", "size_mm": 78}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B9_%E3%82%BF%E3%82%A4%E7%94%A3_%E3%83%89%E3%82%A4%E3%82%B1%E3%82%B5%E3%83%83%E3%83%88_83.3%E3%8E%9C.jpg/1280px-%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B9_%E3%82%BF%E3%82%A4%E7%94%A3_%E3%83%89%E3%82%A4%E3%82%B1%E3%82%B5%E3%83%83%E3%83%88_83.3%E3%8E%9C.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/%E3%83%A9%E3%82%AA%E3%82%B9%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B983%E3%8E%9C.jpg/1280px-%E3%83%A9%E3%82%AA%E3%82%B9%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B983%E3%8E%9C.jpg']::TEXT[], FALSE, 439),
  ('Antaeus stag beetle (Dorcus antaeus), pair (1 male + 1 female)', 'ด้วงคีมแอนเทียส (Dorcus antaeus) คู่ (ผู้ 1 เมีย 1)', 'A glossy black stag with wide, toothed jaws from the cool mountains of northern Thailand. Size about 75 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมดำเงา กรามกว้างมีฟัน จากภูเขาเย็นของภาคเหนือ ขนาดประมาณ 75 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 3400, 2, 'beetle', '{"family": "Stag", "species": "Dorcus antaeus", "locality": "Doi Inthanon, Thailand", "sex": "pair", "stage": "adult", "size_mm": 75}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/%E3%83%A9%E3%82%AA%E3%82%B9%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B983%E3%8E%9C.jpg/1280px-%E3%83%A9%E3%82%AA%E3%82%B9%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B983%E3%8E%9C.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B9_%E3%82%BF%E3%82%A4%E7%94%A3_%E3%83%89%E3%82%A4%E3%82%B1%E3%82%B5%E3%83%83%E3%83%88_83.3%E3%8E%9C.jpg/1280px-%E3%82%A2%E3%83%B3%E3%82%BF%E3%82%A8%E3%82%A6%E3%82%B9_%E3%82%BF%E3%82%A4%E7%94%A3_%E3%83%89%E3%82%A4%E3%82%B1%E3%82%B5%E3%83%83%E3%83%88_83.3%E3%8E%9C.jpg']::TEXT[], FALSE, 1370),
  ('Curved-tooth stag beetle (Dorcus curvidens), male', 'ด้วงคีมเคอร์วิเดนส์ (Dorcus curvidens) ตัวผู้', 'Long, smoothly curved jaws on a lean black body. Size about 76 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กรามโค้งยาวเรียบ ลำตัวดำเพรียว ขนาดประมาณ 76 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1700, 3, 'beetle', '{"family": "Stag", "species": "Dorcus curvidens", "locality": "Laos", "sex": "male", "stage": "adult", "size_mm": 76}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/3/3f/Dorcus_curvidens_hopei_sjh.jpg']::TEXT[], FALSE, 1601),
  ('Javan stag beetle (Dorcus bucephalus), male', 'ด้วงคีมชวา (Dorcus bucephalus) ตัวผู้', 'A thick-bodied stag with wide jaws that curve sharply inward at the tips. Size about 82 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมลำตัวหนา กรามกว้าง ปลายโค้งเข้าแหลม ขนาดประมาณ 82 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2200, 2, 'beetle', '{"family": "Stag", "species": "Dorcus bucephalus", "locality": "Java, Indonesia", "sex": "male", "stage": "adult", "size_mm": 82}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/DorcusbucephalusMale.JPG/1280px-DorcusbucephalusMale.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/DorcusbucephalusPair.JPG/1280px-DorcusbucephalusPair.JPG']::TEXT[], FALSE, 432),
  ('European stag beetle (Lucanus cervus), male', 'ด้วงคีมยุโรป (Lucanus cervus) ตัวผู้', 'Europe''s best-known stag, with antler-like reddish jaws. Size about 70 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมที่ดังที่สุดของยุโรป กรามสีแดงคล้ายเขากวาง ขนาดประมาณ 70 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1900, 2, 'beetle', '{"family": "Stag", "species": "Lucanus cervus", "locality": "Europe (captive bred)", "sex": "male", "stage": "adult", "size_mm": 70}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Lucanus_cervus_Femelle_MHNT.jpg/1280px-Lucanus_cervus_Femelle_MHNT.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Lucanus_cervus_male_2017_G1.jpg/1280px-Lucanus_cervus_male_2017_G1.jpg']::TEXT[], FALSE, 863),
  ('Miyama stag beetle (Lucanus maculifemoratus), male', 'ด้วงคีมมิยามะ (Lucanus maculifemoratus) ตัวผู้', 'A golden-haired mountain stag with an ear-like crest on the head. Size about 68 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมภูเขาขนสีทอง มีสันที่หัวคล้ายหู ขนาดประมาณ 68 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1400, 4, 'beetle', '{"family": "Stag", "species": "Lucanus maculifemoratus", "locality": "Japan", "sex": "male", "stage": "adult", "size_mm": 68}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/cb/Lucanus_maculifemoratus_maculifemoratus_sjh.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Lucanus_maculifemoratus_taiwanus_%2827399831431%29.jpg/1280px-Lucanus_maculifemoratus_taiwanus_%2827399831431%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Lucanus_maculifemoratus_taiwanus_%2832678357554%29.jpg/1280px-Lucanus_maculifemoratus_taiwanus_%2832678357554%29.jpg']::TEXT[], FALSE, 2294),
  ('Giraffe stag beetle (Prosopocoilus giraffa), male', 'ด้วงคีมยีราฟ (Prosopocoilus giraffa) ตัวผู้', 'The longest stag beetle in the world, with jaws over half its length. Size about 110 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมที่ยาวที่สุดในโลก กรามยาวกว่าครึ่งลำตัว ขนาดประมาณ 110 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2400, 4, 'beetle', '{"family": "Stag", "species": "Prosopocoilus giraffa", "locality": "Mae Hong Son, Thailand", "sex": "male", "stage": "adult", "size_mm": 110}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Prosopocoilus_giraffa_sjh.jpg/1280px-Prosopocoilus_giraffa_sjh.jpg', 'https://upload.wikimedia.org/wikipedia/commons/b/b4/Lucanidae_-_Cladognathus_giraffa.JPG', 'https://upload.wikimedia.org/wikipedia/commons/5/58/Giraffe_stag_beetle_%28Prosopocoilus_giraffa%29%2C_Entomica_1.jpg']::TEXT[], TRUE, 3085),
  ('Giraffe stag beetle (Prosopocoilus giraffa), pair (1 male + 1 female)', 'ด้วงคีมยีราฟ (Prosopocoilus giraffa) คู่ (ผู้ 1 เมีย 1)', 'The longest stag beetle in the world, with jaws over half its length. Size about 105 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงคีมที่ยาวที่สุดในโลก กรามยาวกว่าครึ่งลำตัว ขนาดประมาณ 105 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 3200, 2, 'beetle', '{"family": "Stag", "species": "Prosopocoilus giraffa", "locality": "Mae Hong Son, Thailand", "sex": "pair", "stage": "adult", "size_mm": 105}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/b/b4/Lucanidae_-_Cladognathus_giraffa.JPG', 'https://upload.wikimedia.org/wikipedia/commons/5/58/Giraffe_stag_beetle_%28Prosopocoilus_giraffa%29%2C_Entomica_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Prosopocoilus_giraffa_sjh.jpg/1280px-Prosopocoilus_giraffa_sjh.jpg']::TEXT[], FALSE, 756),
  ('Giraffe stag beetle (Prosopocoilus giraffa), L3 larva', 'ด้วงคีมยีราฟ (Prosopocoilus giraffa) หนอนระยะ L3', 'The longest stag beetle in the world, with jaws over half its length. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'ด้วงคีมที่ยาวที่สุดในโลก กรามยาวกว่าครึ่งลำตัว เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 400, 10, 'beetle', '{"family": "Stag", "species": "Prosopocoilus giraffa", "locality": "Mae Hong Son, Thailand", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Larva_of_hirata-kun.jpg/1280px-Larva_of_hirata-kun.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a3/Noko_larva.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Prosopocoilus_giraffa_sjh.jpg/1280px-Prosopocoilus_giraffa_sjh.jpg']::TEXT[], FALSE, 487),
  ('Nokogiri stag beetle (Prosopocoilus inclinatus), male', 'ด้วงคีมโนโคกิริ (Prosopocoilus inclinatus) ตัวผู้', 'Saw-toothed curved jaws and a red-brown shell; quick to breed. Size about 62 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กรามโค้งหยักเหมือนเลื่อย ผิวน้ำตาลแดง เพาะพันธุ์ได้เร็ว ขนาดประมาณ 62 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 650, 8, 'beetle', '{"family": "Stag", "species": "Prosopocoilus inclinatus", "locality": "Japan", "sex": "male", "stage": "adult", "size_mm": 62}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Prosopocoilus_inclinatus_sjh.jpg/1280px-Prosopocoilus_inclinatus_sjh.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Psalidoremus_%28%3DLucanus%2C_Prosopocoilus%29_inclinatus_inclinatus_Motschulsky%2C_1857_male_%283953206743%29.jpg/1280px-Psalidoremus_%28%3DLucanus%2C_Prosopocoilus%29_inclinatus_inclinatus_Motschulsky%2C_1857_male_%283953206743%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/14/Prosopocoilus_inclinatus_by_OpenCage.jpg']::TEXT[], FALSE, 2368),
  ('Metallic stag beetle (Cyclommatus metallifer), male', 'ด้วงคีมเมทัลลิเฟอร์ (Cyclommatus metallifer) ตัวผู้', 'Thin, very long jaws and a golden-green metallic body. Size about 88 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กรามเรียวยาวมาก ลำตัวสีเขียวทองเหลือบโลหะ ขนาดประมาณ 88 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1800, 4, 'beetle', '{"family": "Stag", "species": "Cyclommatus metallifer", "locality": "Sulawesi, Indonesia", "sex": "male", "stage": "adult", "size_mm": 88}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Cyclommatus_metallifer_m1.jpg/1280px-Cyclommatus_metallifer_m1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Cyclommatus_metallifer_metallifer_%28Boisduval%2C1835%29_male_%283772658452%29.jpg/1280px-Cyclommatus_metallifer_metallifer_%28Boisduval%2C1835%29_male_%283772658452%29.jpg']::TEXT[], FALSE, 949),
  ('Elaphus stag beetle (Cyclommatus elaphus), male', 'ด้วงคีมเอลาฟัส (Cyclommatus elaphus) ตัวผู้', 'A large Cyclommatus with bronze sheen and long, finely toothed jaws. Size about 94 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงสกุล Cyclommatus ตัวใหญ่ ผิวเหลือบทองแดง กรามยาวฟันละเอียด ขนาดประมาณ 94 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2300, 2, 'beetle', '{"family": "Stag", "species": "Cyclommatus elaphus", "locality": "Sumatra, Indonesia", "sex": "male", "stage": "adult", "size_mm": 94}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Cyclommatus_elaphus.JPG/1280px-Cyclommatus_elaphus.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Cyclommatus_elaphus%2C_imperator_and_elaphus_truncatus.jpg/1280px-Cyclommatus_elaphus%2C_imperator_and_elaphus_truncatus.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Cyclommatus_elaphus_m2.jpg/1280px-Cyclommatus_elaphus_m2.jpg']::TEXT[], FALSE, 2180),
  ('Parry''s stag beetle (Hexarthrius parryi), male', 'ด้วงคีมแพร์รี (Hexarthrius parryi) ตัวผู้', 'Black jaws over tan-and-black wing cases; a bold, eye-catching stag. Size about 80 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'กรามดำ ปีกสีน้ำตาลอ่อนสลับดำ สวยสะดุดตา ขนาดประมาณ 80 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 2100, 3, 'beetle', '{"family": "Stag", "species": "Hexarthrius parryi", "locality": "Myanmar", "sex": "male", "stage": "adult", "size_mm": 80}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/7/7e/Fighting_giant_stag_beetle_%28Hexarthrius_parryi%29%2C_Entomica.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Lucanidae_-_Hexarthrius_parryi_paradoxus.JPG/1280px-Lucanidae_-_Hexarthrius_parryi_paradoxus.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Hexarthrius_parryi_paradoxus_Moellenkamp%2C_1897_male_%283576468514%29_%282%29.jpg/1280px-Hexarthrius_parryi_paradoxus_Moellenkamp%2C_1897_male_%283576468514%29_%282%29.jpg']::TEXT[], FALSE, 911),
  ('Rainbow stag beetle (Phalacrognathus muelleri), male', 'ด้วงคีมสายรุ้ง (Phalacrognathus muelleri) ตัวผู้', 'Metallic rainbow colours from green to copper; one of the most beautiful beetles kept. Size about 62 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีรุ้งเหลือบโลหะตั้งแต่เขียวถึงทองแดง หนึ่งในด้วงที่สวยที่สุด ขนาดประมาณ 62 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 3800, 2, 'beetle', '{"family": "Stag", "species": "Phalacrognathus muelleri", "locality": "Queensland, Australia", "sex": "male", "stage": "adult", "size_mm": 62}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/0/06/Phalacrognathus_muelleri_sjh.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Rainbow_stag_beetle.jpg/1280px-Rainbow_stag_beetle.jpg']::TEXT[], TRUE, 1802),
  ('Rainbow stag beetle (Phalacrognathus muelleri), pair (1 male + 1 female)', 'ด้วงคีมสายรุ้ง (Phalacrognathus muelleri) คู่ (ผู้ 1 เมีย 1)', 'Metallic rainbow colours from green to copper; one of the most beautiful beetles kept. Size about 60 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีรุ้งเหลือบโลหะตั้งแต่เขียวถึงทองแดง หนึ่งในด้วงที่สวยที่สุด ขนาดประมาณ 60 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 5200, 1, 'beetle', '{"family": "Stag", "species": "Phalacrognathus muelleri", "locality": "Queensland, Australia", "sex": "pair", "stage": "adult", "size_mm": 60}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Rainbow_stag_beetle.jpg/1280px-Rainbow_stag_beetle.jpg', 'https://upload.wikimedia.org/wikipedia/commons/0/06/Phalacrognathus_muelleri_sjh.jpg']::TEXT[], FALSE, 1273),
  ('Golden stag beetle (Lamprima adolphinae), pair (1 male + 1 female)', 'ด้วงคีมทอง (Lamprima adolphinae) คู่ (ผู้ 1 เมีย 1)', 'Small and dazzling: metallic gold, green or purple, with upturned jaws. Size about 40 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ตัวเล็กแต่สะดุดตา สีทอง เขียว หรือม่วงเหลือบโลหะ กรามงอนขึ้น ขนาดประมาณ 40 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1500, 4, 'beetle', '{"family": "Stag", "species": "Lamprima adolphinae", "locality": "Papua New Guinea", "sex": "pair", "stage": "adult", "size_mm": 40}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/5/5e/Lamprima_adolphinae_sjh.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Lamprima_adolphinae%2C_Megalorhinia_harrisi%2C_Mecocerus_sp.jpg/1280px-Lamprima_adolphinae%2C_Megalorhinia_harrisi%2C_Mecocerus_sp.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Stag_Beetle_%28Lamprima_adolphinae%29_%288430587514%29.jpg/1280px-Stag_Beetle_%28Lamprima_adolphinae%29_%288430587514%29.jpg']::TEXT[], FALSE, 1904),
  ('Cuvera stag beetle (Odontolabis cuvera), male', 'ด้วงคีมคูเวรา (Odontolabis cuvera) ตัวผู้', 'Shiny black with orange-edged wing cases; an Odontolabis native to Thai forests. Size about 72 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ดำเงา ขอบปีกสีส้ม ด้วงคีมสกุล Odontolabis ที่พบในป่าไทย ขนาดประมาณ 72 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1300, 4, 'beetle', '{"family": "Stag", "species": "Odontolabis cuvera", "locality": "Nan, Thailand", "sex": "male", "stage": "adult", "size_mm": 72}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/b/b4/OdontolabisCuveraJBNHS.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/92/Odontolabis_cuvera_India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Odontolabis_cuvera_sjh.jpg/1280px-Odontolabis_cuvera_sjh.jpg']::TEXT[], FALSE, 635),
  ('Goliath beetle (Goliathus goliatus), male', 'ด้วงโกไลแอธ (Goliathus goliatus) ตัวผู้', 'One of the heaviest insects on earth, with bold black-and-white markings. Size about 98 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'หนึ่งในแมลงที่หนักที่สุดในโลก ลายขาวดำชัดเจน ขนาดประมาณ 98 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 6500, 2, 'beetle', '{"family": "Flower", "species": "Goliathus goliatus", "locality": "Cameroon", "sex": "male", "stage": "adult", "size_mm": 98}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Goliathus_goliatus_vol.jpg/1280px-Goliathus_goliatus_vol.jpg']::TEXT[], TRUE, 2026),
  ('Goliath beetle (Goliathus goliatus), pair (1 male + 1 female)', 'ด้วงโกไลแอธ (Goliathus goliatus) คู่ (ผู้ 1 เมีย 1)', 'One of the heaviest insects on earth, with bold black-and-white markings. Size about 92 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'หนึ่งในแมลงที่หนักที่สุดในโลก ลายขาวดำชัดเจน ขนาดประมาณ 92 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 9000, 1, 'beetle', '{"family": "Flower", "species": "Goliathus goliatus", "locality": "Cameroon", "sex": "pair", "stage": "adult", "size_mm": 92}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Goliathus_goliatus_vol.jpg/1280px-Goliathus_goliatus_vol.jpg']::TEXT[], FALSE, 1997),
  ('Oriental Goliath beetle (Goliathus orientalis), male', 'ด้วงโกไลแอธตะวันออก (Goliathus orientalis) ตัวผู้', 'A cream-and-black Goliath from East Africa, slightly smaller and calmer. Size about 90 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'โกไลแอธจากแอฟริกาตะวันออก ลายครีมดำ ตัวเล็กกว่าเล็กน้อยและนิ่งกว่า ขนาดประมาณ 90 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 5200, 2, 'beetle', '{"family": "Flower", "species": "Goliathus orientalis", "locality": "Tanzania", "sex": "male", "stage": "adult", "size_mm": 90}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/b/bf/Scarabaeidae_-_Goliathus_orientalis.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/83/Goliathus_orientalis_preissei.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Goliathus_regius%2C_Goliathus_cacicus%2C_Goliathus_orientalis_%2810656790965%29.jpg/1280px-Goliathus_regius%2C_Goliathus_cacicus%2C_Goliathus_orientalis_%2810656790965%29.jpg']::TEXT[], FALSE, 1928),
  ('Royal Goliath beetle (Goliathus regius), male', 'ด้วงโกไลแอธหลวง (Goliathus regius) ตัวผู้', 'White wing cases striped with black; the showiest of the Goliaths. Size about 95 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ปีกขาวคาดดำ สวยที่สุดในกลุ่มโกไลแอธ ขนาดประมาณ 95 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 7200, 1, 'beetle', '{"family": "Flower", "species": "Goliathus regius", "locality": "Ghana", "sex": "male", "stage": "adult", "size_mm": 95}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/6/68/Goliathus_regius%2C_2006-12-02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Goliathus_regius_KL.jpg/1280px-Goliathus_regius_KL.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Goliathus-regius_hg.jpg/1280px-Goliathus-regius_hg.jpg']::TEXT[], FALSE, 1659),
  ('Giant flower beetle (Mecynorrhina torquata), male', 'ด้วงดอกไม้ยักษ์ (Mecynorrhina torquata) ตัวผู้', 'Metallic green with white stripes and a forked head horn; flies readily in daylight. Size about 78 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเขียวเหลือบโลหะลายขาว มีเขาหัวแฉก บินได้ดีตอนกลางวัน ขนาดประมาณ 78 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1200, 5, 'beetle', '{"family": "Flower", "species": "Mecynorrhina torquata", "locality": "Cameroon", "sex": "male", "stage": "adult", "size_mm": 78}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Mecynorrhina_torquata_immaculicollis_-_Crop.jpg/1280px-Mecynorrhina_torquata_immaculicollis_-_Crop.jpg']::TEXT[], TRUE, 1450),
  ('Giant flower beetle (Mecynorrhina torquata), pair (1 male + 1 female)', 'ด้วงดอกไม้ยักษ์ (Mecynorrhina torquata) คู่ (ผู้ 1 เมีย 1)', 'Metallic green with white stripes and a forked head horn; flies readily in daylight. Size about 74 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเขียวเหลือบโลหะลายขาว มีเขาหัวแฉก บินได้ดีตอนกลางวัน ขนาดประมาณ 74 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1800, 4, 'beetle', '{"family": "Flower", "species": "Mecynorrhina torquata", "locality": "Cameroon", "sex": "pair", "stage": "adult", "size_mm": 74}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Mecynorrhina_torquata_immaculicollis_-_Crop.jpg/1280px-Mecynorrhina_torquata_immaculicollis_-_Crop.jpg']::TEXT[], FALSE, 121),
  ('Giant flower beetle (Mecynorrhina torquata), 3 L3 larvae', 'ด้วงดอกไม้ยักษ์ (Mecynorrhina torquata) หนอนระยะ L3 3 ตัว', 'Metallic green with white stripes and a forked head horn; flies readily in daylight. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'สีเขียวเหลือบโลหะลายขาว มีเขาหัวแฉก บินได้ดีตอนกลางวัน เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 250, 15, 'beetle', '{"family": "Flower", "species": "Mecynorrhina torquata", "locality": "Cameroon", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Mecynorrhina_torquata_ugandensis_-_Third_instar_larva.jpg/1280px-Mecynorrhina_torquata_ugandensis_-_Third_instar_larva.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/11/Rosenk%C3%A4ferraupe_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Mecynorrhina_torquata_immaculicollis_-_Crop.jpg/1280px-Mecynorrhina_torquata_immaculicollis_-_Crop.jpg']::TEXT[], FALSE, 1402),
  ('Polyphemus flower beetle (Mecynorrhina polyphemus), pair (1 male + 1 female)', 'ด้วงดอกไม้โพลีฟีมัส (Mecynorrhina polyphemus) คู่ (ผู้ 1 เมีย 1)', 'Velvety green with fine cream lines; a hardy flower beetle for display. Size about 62 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเขียวกำมะหยี่ลายเส้นครีม ด้วงดอกไม้แข็งแรงเหมาะโชว์ ขนาดประมาณ 62 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1400, 4, 'beetle', '{"family": "Flower", "species": "Mecynorrhina polyphemus", "locality": "Cameroon", "sex": "pair", "stage": "adult", "size_mm": 62}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Chelorrhina_polyphemus_%28Mecynorrhina_polyphemus%29_male.JPG/1280px-Chelorrhina_polyphemus_%28Mecynorrhina_polyphemus%29_male.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Mecynorhina_polyphemus_-_4.jpg/1280px-Mecynorhina_polyphemus_-_4.jpg']::TEXT[], FALSE, 2383),
  ('Derby''s flower beetle (Dicronorhina derbyana), pair (1 male + 1 female)', 'ด้วงดอกไม้ดาร์บี้ (Dicronorhina derbyana) คู่ (ผู้ 1 เมีย 1)', 'Shimmering green with white stripes and a small Y-shaped horn on males. Size about 42 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเขียวแวววาวลายขาว ตัวผู้มีเขาเล็กรูปตัว Y ขนาดประมาณ 42 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 950, 5, 'beetle', '{"family": "Flower", "species": "Dicronorhina derbyana", "locality": "Kenya", "sex": "pair", "stage": "adult", "size_mm": 42}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Dicranorrhina_derbyana_layardi_%28aka%29.jpg/1280px-Dicranorrhina_derbyana_layardi_%28aka%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Dicronorhina_derbyana_konya%2C_Turkey.jpg/1280px-Dicronorhina_derbyana_konya%2C_Turkey.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Dicronorhina_derbyana_layardi.jpg/1280px-Dicronorhina_derbyana_layardi.jpg']::TEXT[], FALSE, 1764),
  ('Gralli flower beetle (Eudicella gralli), pair (1 male + 1 female)', 'ด้วงดอกไม้กราลลี่ (Eudicella gralli) คู่ (ผู้ 1 เมีย 1)', 'Green, orange and black with a two-pronged head horn; breeds easily in flake soil. Size about 38 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเขียว ส้ม ดำ เขาหัวสองแฉก เพาะในดินหมักได้ง่าย ขนาดประมาณ 38 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 690, 6, 'beetle', '{"family": "Flower", "species": "Eudicella gralli", "locality": "Cameroon", "sex": "pair", "stage": "adult", "size_mm": 38}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Eudicella-gralli.jpg/1280px-Eudicella-gralli.jpg']::TEXT[], FALSE, 75),
  ('Spotted flower beetle (Stephanorrhina guttata), trio (1 male + 2 females)', 'ด้วงดอกไม้ลายจุด (Stephanorrhina guttata) ทริโอ (ผู้ 1 เมีย 2)', 'Small, metallic green with white spots; lively and easy to breed. Size about 25 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ตัวเล็ก สีเขียวเหลือบลายจุดขาว คล่องแคล่ว เพาะง่าย ขนาดประมาณ 25 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 590, 8, 'beetle', '{"family": "Flower", "species": "Stephanorrhina guttata", "locality": "Cameroon", "sex": "trio", "stage": "adult", "size_mm": 25}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Stephanorrhina-guttata.jpg/1280px-Stephanorrhina-guttata.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Scarabaeidae_-_Stephanorrhina_guttata.JPG/1280px-Scarabaeidae_-_Stephanorrhina_guttata.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Stephanorrhina_guttata_guttata_%28Olivier%2C_1789%29.png/1280px-Stephanorrhina_guttata_guttata_%28Olivier%2C_1789%29.png']::TEXT[], FALSE, 1906),
  ('African jewel flower beetle (Chlorocala africana), pair (1 male + 1 female)', 'ด้วงดอกไม้อัญมณี (Chlorocala africana) คู่ (ผู้ 1 เมีย 1)', 'Jewel colours from green to red and blue; very active in daylight. Size about 28 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีอัญมณีตั้งแต่เขียว แดง ถึงน้ำเงิน ว่องไวตอนกลางวัน ขนาดประมาณ 28 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 650, 6, 'beetle', '{"family": "Flower", "species": "Chlorocala africana", "locality": "Uganda", "sex": "pair", "stage": "adult", "size_mm": 28}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/4/46/Chlorocales_africana_oertzeni.jpg', 'https://upload.wikimedia.org/wikipedia/commons/b/b4/Smaragdesthes_africana_Moscow.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4d/Scarabaeidae_-_Smaragdesthes_africana_africana.JPG']::TEXT[], FALSE, 57),
  ('Sun beetle (Pachnoda marginata), 5 adults, unsexed', 'ด้วงดอกไม้ซันบีเทิล (Pachnoda marginata) ตัวเต็มวัย 5 ตัว ไม่แยกเพศ', 'Yellow-and-brown, calm and easy: the best flower beetle for beginners and classrooms. Size about 25 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเหลืองน้ำตาล นิสัยนิ่ง เลี้ยงง่าย ด้วงดอกไม้ที่ดีที่สุดสำหรับมือใหม่และห้องเรียน ขนาดประมาณ 25 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 290, 20, 'beetle', '{"family": "Flower", "species": "Pachnoda marginata", "locality": "Cameroon (captive bred)", "sex": "unsexed", "stage": "adult", "size_mm": 25}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/PachnodaMarginataPerigrina.jpg/1280px-PachnodaMarginataPerigrina.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Sun_beetle_%28Pachnoda_marginata%29.jpg/1280px-Sun_beetle_%28Pachnoda_marginata%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Pachnoda_marginata_aurantia_%28Herbst%2C_1790%29_%283406981252%29.jpg/1280px-Pachnoda_marginata_aurantia_%28Herbst%2C_1790%29_%283406981252%29.jpg']::TEXT[], FALSE, 68),
  ('Sun beetle (Pachnoda marginata), 10 L3 larvae', 'ด้วงดอกไม้ซันบีเทิล (Pachnoda marginata) หนอนระยะ L3 10 ตัว', 'Yellow-and-brown, calm and easy: the best flower beetle for beginners and classrooms. Raised in fermented flake soil; keep in its own cup at 22–26 °C until it pupates.', 'สีเหลืองน้ำตาล นิสัยนิ่ง เลี้ยงง่าย ด้วงดอกไม้ที่ดีที่สุดสำหรับมือใหม่และห้องเรียน เลี้ยงในดินหมัก แยกเลี้ยงในถ้วยที่ 22–26 °C จนเข้าดักแด้', 190, 25, 'beetle', '{"family": "Flower", "species": "Pachnoda marginata", "locality": "Cameroon (captive bred)", "sex": "unsexed", "stage": "L3"}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/1/11/Rosenk%C3%A4ferraupe_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Rosenk%C3%A4ferraupe_3.jpg/1280px-Rosenk%C3%A4ferraupe_3.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/PachnodaMarginataPerigrina.jpg/1280px-PachnodaMarginataPerigrina.jpg']::TEXT[], FALSE, 1899),
  ('Rose chafer (Cetonia aurata), 3 adults, unsexed', 'ด้วงกุหลาบ (Cetonia aurata) ตัวเต็มวัย 3 ตัว ไม่แยกเพศ', 'Bright metallic green; a gentle species that feeds on fruit and jelly. Size about 20 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีเขียวเหลือบโลหะสดใส นิสัยไม่ดุ กินผลไม้และเยลลี่ ขนาดประมาณ 20 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 250, 15, 'beetle', '{"family": "Flower", "species": "Cetonia aurata", "locality": "Europe (captive bred)", "sex": "unsexed", "stage": "adult", "size_mm": 20}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Cetonia-aurata.jpg/1280px-Cetonia-aurata.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Rose_chafers_%28Cetonia_aurata%29_on_thistle_%28Carduus_sp.%29.jpg/1280px-Rose_chafers_%28Cetonia_aurata%29_on_thistle_%28Carduus_sp.%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Cetonia_aurata_take_off_composition_05172009.jpg/1280px-Cetonia_aurata_take_off_composition_05172009.jpg']::TEXT[], FALSE, 50),
  ('Rucker''s flower beetle (Jumnos ruckeri), pair (1 male + 1 female)', 'ด้วงดอกไม้รักเกอร์ (Jumnos ruckeri) คู่ (ผู้ 1 เมีย 1)', 'A large Asian flower beetle, green with yellow side marks, from western Thailand. Size about 40 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'ด้วงดอกไม้เอเชียตัวใหญ่ สีเขียวขอบเหลือง จากภาคตะวันตกของไทย ขนาดประมาณ 40 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1100, 3, 'beetle', '{"family": "Flower", "species": "Jumnos ruckeri", "locality": "Tak, Thailand", "sex": "pair", "stage": "adult", "size_mm": 40}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Scarabaeidae_-_Jumnos_ruckeri.jpg/1280px-Scarabaeidae_-_Jumnos_ruckeri.jpg']::TEXT[], FALSE, 1331),
  ('Flame flower beetle (Torynorrhina flammea), male', 'ด้วงดอกไม้เปลวไฟ (Torynorrhina flammea) ตัวผู้', 'Mirror-bright red, green or purple; a Thai native that glows under light. Size about 32 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีแดง เขียว หรือม่วงสะท้อนแสงเหมือนกระจก ด้วงพื้นเมืองไทยที่เปล่งประกาย ขนาดประมาณ 32 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 890, 5, 'beetle', '{"family": "Flower", "species": "Torynorrhina flammea", "locality": "Chiang Mai, Thailand", "sex": "male", "stage": "adult", "size_mm": 32}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/9/9f/Torynorrhina_flammea_chicheryi_and_Formica_Rufa_Richard_Bartz.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/12/Scarabaeidae_-_Torynorrhina_flammea.JPG']::TEXT[], FALSE, 2392),
  ('Flame flower beetle (Torynorrhina flammea), pair (1 male + 1 female)', 'ด้วงดอกไม้เปลวไฟ (Torynorrhina flammea) คู่ (ผู้ 1 เมีย 1)', 'Mirror-bright red, green or purple; a Thai native that glows under light. Size about 30 mm. Captive bred, active and feeding on jelly. Ships Monday to Wednesday under our Live Arrival Guarantee.', 'สีแดง เขียว หรือม่วงสะท้อนแสงเหมือนกระจก ด้วงพื้นเมืองไทยที่เปล่งประกาย ขนาดประมาณ 30 มม. เพาะเลี้ยงในฟาร์ม แข็งแรง กินเยลลี่ดี ส่งวันจันทร์ถึงพุธ พร้อมรับประกันถึงมือมีชีวิต', 1300, 3, 'beetle', '{"family": "Flower", "species": "Torynorrhina flammea", "locality": "Chiang Mai, Thailand", "sex": "pair", "stage": "adult", "size_mm": 30}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/1/12/Scarabaeidae_-_Torynorrhina_flammea.JPG', 'https://upload.wikimedia.org/wikipedia/commons/9/9f/Torynorrhina_flammea_chicheryi_and_Formica_Rufa_Richard_Bartz.jpg']::TEXT[], FALSE, 593),
  ('Beetle jelly 16 g, banana (pack of 10)', 'เยลลี่ด้วง 16 กรัม รสกล้วย (แพ็ค 10)', 'Ready-to-serve jelly cups for adult beetles. Banana flavour, high sugar for active males. Keeps fruit flies away better than fresh fruit.', 'เยลลี่ถ้วยพร้อมเสิร์ฟสำหรับด้วงตัวเต็มวัย รสกล้วย น้ำตาลสูง เหมาะกับตัวผู้ที่ใช้พลังเยอะ แมลงหวี่ตอมน้อยกว่าผลไม้สด', 59, 120, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg']::TEXT[], TRUE, 2497),
  ('Beetle jelly 16 g, banana (pack of 50)', 'เยลลี่ด้วง 16 กรัม รสกล้วย (แพ็ค 50)', 'The same banana jelly in a breeder pack; enough for a pair for about two months.', 'เยลลี่รสกล้วยแบบแพ็คนักเพาะ พอสำหรับด้วงหนึ่งคู่ประมาณสองเดือน', 249, 60, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg']::TEXT[], FALSE, 698),
  ('High-protein beetle jelly 16 g (pack of 10)', 'เยลลี่โปรตีนสูง 16 กรัม (แพ็ค 10)', 'Extra protein for females before and during egg laying. Feed alongside regular jelly.', 'เสริมโปรตีนสำหรับตัวเมียช่วงก่อนและระหว่างวางไข่ ให้คู่กับเยลลี่ปกติ', 79, 90, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg']::TEXT[], TRUE, 2899),
  ('High-protein beetle jelly 16 g (pack of 50)', 'เยลลี่โปรตีนสูง 16 กรัม (แพ็ค 50)', 'Breeder pack of high-protein jelly for setting up several females at once.', 'เยลลี่โปรตีนสูงแพ็คนักเพาะ สำหรับเซ็ตตัวเมียหลายตัวพร้อมกัน', 329, 40, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg']::TEXT[], FALSE, 1520),
  ('Royal jelly beetle jelly 16 g (pack of 10)', 'เยลลี่นมผึ้ง 16 กรัม (แพ็ค 10)', 'Premium jelly with royal jelly, for show animals and long-lived stag beetles.', 'เยลลี่พรีเมียมผสมนมผึ้ง สำหรับด้วงโชว์และด้วงคีมที่อายุยืน', 99, 70, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Weiselzellen_79a.jpg/1280px-Weiselzellen_79a.jpg']::TEXT[], FALSE, 41),
  ('Apple beetle jelly 16 g (pack of 10)', 'เยลลี่ด้วง 16 กรัม รสแอปเปิล (แพ็ค 10)', 'A lighter apple flavour that flower beetles take readily.', 'รสแอปเปิลกลิ่นอ่อน ด้วงดอกไม้ชอบกิน', 59, 80, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Apple_slices%2C_2013_%2801%29.jpg/1280px-Apple_slices%2C_2013_%2801%29.jpg']::TEXT[], FALSE, 2292),
  ('Honey beetle jelly 16 g (pack of 10)', 'เยลลี่ด้วง 16 กรัม รสน้ำผึ้ง (แพ็ค 10)', 'Honey flavour with a firm set that does not spill in transport boxes.', 'รสน้ำผึ้ง เนื้อแน่น ไม่หกเลอะเวลาเดินทาง', 65, 80, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Three_French_monofloral_honey_jars.jpg/1280px-Three_French_monofloral_honey_jars.jpg']::TEXT[], FALSE, 65),
  ('Dried banana slices for beetles, 200 g', 'กล้วยตากสำหรับด้วง 200 กรัม', 'Sun-dried banana without additives. Soak briefly before serving to adult beetles.', 'กล้วยตากไม่มีสารปรุงแต่ง แช่น้ำสักครู่ก่อนให้ด้วงตัวเต็มวัย', 89, 50, 'food', '{}'::JSONB, ARRAY['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Dried_banana_chips.jpg/1280px-Dried_banana_chips.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Banana_Chips_by_Ramesh_Kunnappully_20210820_100657.jpg/1280px-Banana_Chips_by_Ramesh_Kunnappully_20210820_100657.jpg']::TEXT[], FALSE, 364),
  ('Jelly feeding platform (log with 2 holes)', 'ขอนวางเยลลี่ (2 หลุม)', 'A wooden feeding block that holds two jelly cups upright so beetles cannot tip them over.', 'ขอนไม้วางถ้วยเยลลี่ได้สองถ้วย ตั้งตรง ด้วงคว่ำไม่ได้', 45, 100, 'food', '{}'::JSONB, ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c1/%E6%98%86%E8%99%AB%E3%82%BC%E3%83%AA%E3%83%BC_%282303042826%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/3/3a/Oak_log%2C_Ham_Clump_-_geograph.org.uk_-_4884818.jpg']::TEXT[], FALSE, 187),
